return {["fb24_01"]={["dsc"]=[[报国寺是峨眉山最大寺院之一。寺庙倚山建造，弥勒殿、大雄殿、七佛殿逐级升高，规模宏大。殿内佛像金光闪闪，气宇轩昂。寺内芳草迷径，花开不绝。]],["id"]=[[fb24_01]],["leftDown"]=[[fb24_13]],["name"]=[[报国寺]],["permission"]=2,["right"]=[[fb24_02]],["role1"]=[[fb24r01_1]],["stepMusic"]=[[jiaobu]]},["fb24_02"]={["dsc"]=[[报国寺为峨眉出入之门户。山上有一块大匾。寺外苍楠环卫，翠柏掩映。由此一路向西上开始登峨眉山，北面下山是一条弯弯的石阶路。]],["fightBackground"]=[[山外]],["id"]=[[fb24_02]],["item1"]=[[lbr02_2]],["item2"]=[[lbr02_3]],["item3"]=[[dhpd]],["left"]=[[fb24_01]],["name"]=[[山门]],["permission"]=2,["role1"]=[[fb24r02_1]],["role2"]=[[fb24r02_2]],["role3"]=[[fb24r02_3]],["role4"]=[[lbr02_1]],["stepMusic"]=[[jiaobu]]},["fb24_03"]={["dsc"]=[[白龙洞据说是《白蛇传》中的白娘子修炼成仙之处。这里北上至万年庵，南下是清音阁。]],["id"]=[[fb24_03]],["item1"]=[[cg2item1]],["name"]=[[白龙洞]],["permission"]=1,["right"]=[[fb24_04]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_19]]},["fb24_04"]={["down"]=[[fb24_14]],["dsc"]=[[这里是峨眉山的清音阁。此阁位于牛心岭下，东有白龙江，西有黑龙江，两江之水交汇于清音阁下。江上有拱桥两座，分跨黑龙白龙二江，这就是双飞桥。]],["id"]=[[fb24_04]],["left"]=[[fb24_03]],["name"]=[[清音阁]],["permission"]=1,["right"]=[[fb24_05]],["role1"]=[[fb24r04_1]],["stepMusic"]=[[jiaobu]]},["fb24_05"]={["dsc"]=[[中峰寺在白云峰下，这里往北可到清音阁，东下至神水庵。]],["id"]=[[fb24_05]],["left"]=[[fb24_04]],["name"]=[[中峰寺]],["permission"]=1,["right"]=[[fb24_06]],["role1"]=[[fb24r05_1]],["role2"]=[[fb24r05_2]],["stepMusic"]=[[jiaobu]]},["fb24_06"]={["down"]=[[fb24_15]],["dsc"]=[[神水庵位于宝掌峰下，庵前有大峨石和玉液泉，泉出石下，清澈无比，终年不涸。一株大海棠树，已是数百苍龄，抱可数围，高达十余丈。]],["id"]=[[fb24_06]],["left"]=[[fb24_05]],["name"]=[[神水庵]],["permission"]=1,["right"]=[[fb24_07]],["role1"]=[[fb24r06_1]],["stepMusic"]=[[jiaobu]]},["fb24_07"]={["dsc"]=[[纯阳殿海拔一千余米，四面古木苍翠，幽静宜人。殿前有一石，叫普贤石，据说普贤菩萨登山时曾坐在这里休息过。在此可纵观峨眉诸峰，仰望金顶，悬崖峭壁，离天咫尺。]],["id"]=[[fb24_07]],["left"]=[[fb24_06]],["name"]=[[纯阳殿]],["permission"]=1,["right"]=[[fb24_08]],["role1"]=[[fb24r07_1]],["role2"]=[[fb24r07_2]],["stepMusic"]=[[jiaobu]]},["fb24_08"]={["down"]=[[fb24_17]],["dsc"]=[[归云阁，原是唐代福昌达道禅师的道场。宋代绍兴年间，僧人士性又率众重建。归云阁左有玉女峰，西上可抵纯阳殿，东下是观音堂。]],["id"]=[[fb24_08]],["item1"]=[[fb24item8]],["left"]=[[fb24_07]],["name"]=[[归云阁]],["permission"]=1,["right"]=[[fb24_09]],["stepMusic"]=[[jiaobu]]},["fb24_09"]={["dsc"]=[[观音堂高踞坡岗，近临危崖，环境幽静，四周树木蓊郁，悦目赏心。传说入山于此，解脱尘凡；出山于此，解脱险阻，故又名解脱庵。]],["id"]=[[fb24_09]],["item1"]=[[bfitem1]],["left"]=[[fb24_08]],["name"]=[[观音堂]],["permission"]=2,["right"]=[[fb24_10]],["role1"]=[[fb24r09_1]],["stepMusic"]=[[jiaobu]]},["fb24_10"]={["dsc"]=[[这里是峨眉胜地解脱坡。坡下一座小桥，叫解脱桥。行人至此，坐桥上听泉声甚美。当此良辰美景，心无芥蒂，心即解脱。坡上一座庵堂，东下一片密林。]],["fightBackground"]=[[山外]],["id"]=[[fb24_10]],["item1"]=[[ycitem1]],["left"]=[[fb24_09]],["name"]=[[解脱坡]],["permission"]=2,["right"]=[[fb24_11]],["role1"]=[[2019qxcdg1a]],["role2"]=[[2019qxcdg1b]],["stepMusic"]=[[jiaobu]]},["fb24_11"]={["down"]=[[fb24_53]],["dsc"]=[[这是黑森森的一片密林，楠木参天，浓阴蔽日。这里东下二里是报国寺，西边林间隐藏着一座庙宇。]],["fightBackground"]=[[森林内]],["id"]=[[fb24_11]],["left"]=[[fb24_10]],["name"]=[[密林]],["permission"]=2,["right"]=[[fb24_12]],["stepMusic"]=[[jiaobu]]},["fb24_12"]={["dsc"]=[[伏虎寺是入山第一大宝刹，隐伏在高大的乔木林间，四周楠木参天，多达十万余株。伏虎寺气象庄严，规模宏盛。寺刹虽掩覆于翠绿浓黛之中，但屋瓦却无一片落叶。]],["id"]=[[fb24_12]],["left"]=[[fb24_11]],["name"]=[[伏虎寺]],["permission"]=2,["right"]=[[fb24_13]],["role1"]=[[fb24r12_1]],["role2"]=[[fb24r12_2]],["role3"]=[[fb24r12_3]],["stepMusic"]=[[jiaobu]]},["fb24_13"]={["dsc"]=[[这是黑森森的一片密林，楠木参天，浓阴蔽日。这里东下二里是报国寺，西边林间隐藏着一座庙宇。]],["fightBackground"]=[[森林内]],["id"]=[[fb24_13]],["item1"]=[[fb24item9]],["left"]=[[fb24_12]],["name"]=[[密林]],["permission"]=2,["rightUp"]=[[fb24_01]],["stepMusic"]=[[jiaobu]]},["fb24_14"]={["down"]=[[fb24_25]],["dsc"]=[[黑龙江栈道沿黑龙江而建。走在栈道上，只觉道窄人危；俯视深涧，急流飞旋，山静而觉动；仰观头顶，天光如隙，崖开而欲合。栈道南通千佛庵，北至清音阁。]],["fightBackground"]=[[山外]],["id"]=[[fb24_14]],["name"]=[[黑龙江栈道]],["permission"]=2,["role1"]=[[fb24r14_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_04]]},["fb24_15"]={["down"]=[[fb24_16]],["dsc"]=[[福寿庵在神水庵南，庵前有九曲渠、流杯池，古人曾据在此饮酒流杯，观景赋诗，歌咏兴叹，不知夕日。庵旁有株大海棠树，数百苍龄，高达十余丈。]],["id"]=[[fb24_15]],["name"]=[[福寿庵]],["permission"]=1,["stepMusic"]=[[jiaobu]],["up"]=[[fb24_06]]},["fb24_16"]={["dsc"]=[[这里是福寿庵的灵文阁，是主持静照师太传授佛法的地方。两名青衣小尼随侍在旁，似乎在聆听师太的教诲。]],["id"]=[[fb24_16]],["name"]=[[灵文阁]],["permission"]=1,["role1"]=[[fb24r16_1]],["role2"]=[[fb24r16_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_15]]},["fb24_17"]={["dsc"]=[[这是归云阁边的玉女峰，古时州刺史冯楫，曾在此结茅而居，发奋诵读《华严经》，不食人间烟火，于是玉女下凡，为他馈赠食物。]],["id"]=[[fb24_17]],["item1"]=[[ycitem2]],["name"]=[[玉女峰]],["permission"]=2,["role1"]=[[fb24r17_1]],["role2"]=[[fb24r17_100]],["role3"]=[[fb24item102]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_08]]},["fb24_18"]={["dsc"]=[[这里石阶陡折多弯，号称「十二盘」。由此西上可达华严顶，东下则到万年庵。]],["fightBackground"]=[[山外]],["id"]=[[fb24_18]],["leftDown"]=[[fb24_21]],["name"]=[[十二盘]],["permission"]=2,["right"]=[[fb24_19]],["stepMusic"]=[[jiaobu]]},["fb24_19"]={["down"]=[[fb24_03]],["dsc"]=[[万年庵建在一座突起的山峰上，周围古木森森，清泉淙淙，闲步无坎，吟游无坷，景色非常迷人。由此西上过十二盘可达华严顶，南下至白龙洞。]],["id"]=[[fb24_19]],["left"]=[[fb24_18]],["name"]=[[万年庵]],["permission"]=2,["role1"]=[[fb24r19_1]],["role2"]=[[fb24r19_2]],["stepMusic"]=[[jiaobu]]},["fb24_20"]={["dsc"]=[[这里石阶陡折多弯，号称「十二盘」。由此西上可达华严顶，东下则到万年庵。]],["fightBackground"]=[[山外]],["id"]=[[fb24_20]],["leftDown"]=[[fb24_23]],["name"]=[[十二盘]],["permission"]=2,["right"]=[[fb24_21]],["stepMusic"]=[[jiaobu]]},["fb24_21"]={["dsc"]=[[这里石阶陡折多弯，号称「十二盘」。由此西上可达华严顶，东下则到万年庵。]],["fightBackground"]=[[山外]],["id"]=[[fb24_21]],["item1"]=[[fb24item5]],["left"]=[[fb24_20]],["name"]=[[十二盘]],["permission"]=2,["rightUp"]=[[fb24_18]],["stepMusic"]=[[jiaobu]]},["fb24_22"]={["dsc"]=[[华严顶挺拔高峭，风景奇险。这里视野开阔，仰可见金顶巍巍，俯可望群峰罗列，许多蹲伏山间的寺院也在眼底。由此向西过数坡，即到莲花石，东下过十二盘可到万年寺。]],["id"]=[[fb24_22]],["left"]=[[fb24_24]],["name"]=[[华严顶]],["permission"]=2,["right"]=[[fb24_23]],["role1"]=[[fb24r22_1]],["stepMusic"]=[[jiaobu]]},["fb24_23"]={["dsc"]=[[这里石阶陡折多弯，号称「十二盘」。由此西上可达华严顶，东下则到万年庵。]],["fightBackground"]=[[山外]],["id"]=[[fb24_23]],["left"]=[[fb24_22]],["name"]=[[十二盘]],["permission"]=2,["rightUp"]=[[fb24_20]],["stepMusic"]=[[jiaobu]]},["fb24_24"]={["dsc"]=[[这是莲花石。此处岩石纹理纵横，形似莲花，颜如芙蓉，仿佛萼瓣层叠，细蕊欲绽。上有一庵，叫「莲花社」。由此往西上直达洗象池，东下左通华严顶，右通九老洞。]],["fightBackground"]=[[山外]],["id"]=[[fb24_24]],["left"]=[[fb24_33]],["name"]=[[莲花石]],["permission"]=2,["right"]=[[fb24_22]],["role1"]=[[fb24r24_1]],["role2"]=[[fb24r24_2]],["stepMusic"]=[[jiaobu]]},["fb24_25"]={["dsc"]=[[此处是洪椿坪千佛庵。山间小坪坝，四面层峦叠障，峰环岭护；两侧深谷幽岚，溪涧玲叮。坪上古木扶疏，亭亭如盖，山阴沁透，白雾飘游，极为幽静清凉。]],["id"]=[[fb24_25]],["left"]=[[fb24_27]],["name"]=[[千佛庵]],["permission"]=2,["role1"]=[[fb24r25_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_14]]},["fb24_26"]={["dsc"]=[[这是著名的「九十九道拐」，道路纡曲陡竖，千折百回。由此东可至千佛庵，西达九老洞。]],["fightBackground"]=[[山外]],["id"]=[[fb24_26]],["leftDown"]=[[fb24_29]],["name"]=[[九十九道拐]],["permission"]=2,["right"]=[[fb24_27]],["stepMusic"]=[[jiaobu]]},["fb24_27"]={["dsc"]=[[这是著名的「九十九道拐」，道路纡曲陡竖，千折百回。由此东可至千佛庵，西达九老洞。]],["fightBackground"]=[[山外]],["id"]=[[fb24_27]],["left"]=[[fb24_26]],["name"]=[[九十九道拐]],["permission"]=2,["right"]=[[fb24_25]],["stepMusic"]=[[jiaobu]]},["fb24_28"]={["dsc"]=[[这是著名的「九十九道拐」，道路纡曲陡竖，千折百回。由此东可至千佛庵，西达九老洞。]],["fightBackground"]=[[山外]],["id"]=[[fb24_28]],["leftDown"]=[[fb24_30]],["name"]=[[九十九道拐]],["permission"]=2,["right"]=[[fb24_29]],["stepMusic"]=[[jiaobu]]},["fb24_29"]={["dsc"]=[[这是著名的「九十九道拐」，道路纡曲陡竖，千折百回。由此东可至千佛庵，西达九老洞。]],["fightBackground"]=[[山外]],["id"]=[[fb24_29]],["item1"]=[[fb24item11]],["left"]=[[fb24_28]],["name"]=[[九十九道拐]],["permission"]=2,["rightUp"]=[[fb24_26]],["stepMusic"]=[[jiaobu]]},["fb24_30"]={["down"]=[[fb24_45]],["dsc"]=[[这就是峨眉第一大洞，洞内深窈无比，神秘难测。你一走进来，便发觉洞中叉洞多如迷宫，怪异莫测，似乎黝黑无底。还是快快离开吧。]],["id"]=[[fb24_30]],["name"]=[[九老洞口]],["permission"]=2,["rightUp"]=[[fb24_28]],["role1"]=[[fb24r30_1]],["stepMusic"]=[[jiaobu]]},["fb24_31"]={["down"]=[[fb24_34]],["dsc"]=[[洗象池寓于一片冷杉林中，有若白云深处的仙山琼阁。若是云收雾敛、碧空万里、月朗中天时，便觉万籁俱寂，清光无限，宛若身在天宫，彻体生凉。这正是著名的「象池池夜」。]],["id"]=[[fb24_31]],["name"]=[[洗象池]],["permission"]=2,["right"]=[[fb24_32]],["stepMusic"]=[[jiaobu]]},["fb24_32"]={["dsc"]=[[莲花石与洗象池之间，道路陡绝，石栈若齿，直上蓝天，石磴达一千三百多级，是在陡峭山壁上开凿出来的坡道。人行其上，前后顶踵相接，一如登天。]],["fightBackground"]=[[山外]],["id"]=[[fb24_32]],["left"]=[[fb24_31]],["name"]=[[坡道]],["permission"]=2,["right"]=[[fb24_33]],["stepMusic"]=[[jiaobu]]},["fb24_33"]={["dsc"]=[[莲花石与洗象池之间，道路陡绝，石栈若齿，直上蓝天，石磴达一千三百多级，是在陡峭山壁上开凿出来的坡道。人行其上，前后顶踵相接，一如登天。]],["fightBackground"]=[[山外]],["id"]=[[fb24_33]],["item1"]=[[fb24item6]],["left"]=[[fb24_32]],["name"]=[[坡道]],["permission"]=2,["right"]=[[fb24_24]],["stepMusic"]=[[jiaobu]]},["fb24_34"]={["down"]=[[fb24_35]],["dsc"]=[[这是凌云梯，最早是一位叫阿婆多的外国和尚在此缚木架石，以渡行人，又叫「胡僧梯」。此梯北通洗象池，南至雷洞坪。]],["id"]=[[fb24_34]],["name"]=[[凌云梯]],["permission"]=2,["role1"]=[[fb24r34_1]],["role2"]=[[fb24r34_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_31]]},["fb24_35"]={["down"]=[[fb24_36]],["dsc"]=[[雷洞坪一带，道路艰险骇人，路左是蔽日遮天的冷杉林，路右是深不见底的绝壁峡谷。由此往上是「八十四盘」至接引殿，北下到洗象池。]],["id"]=[[fb24_35]],["name"]=[[雷洞坪]],["permission"]=2,["role1"]=[[fb24r35_100]],["role2"]=[[fb24r35_101]],["role3"]=[[fb24r35_102]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_34]]},["fb24_36"]={["dsc"]=[[八十四盘，道路艰险陡峭，迂回盘折，令人不能喘息。路左是蔽日遮天的冷杉林，路右是深不见底的绝壁峡谷。由此往上至接引殿，北下到洗象池。]],["fightBackground"]=[[山外]],["id"]=[[fb24_36]],["leftDown"]=[[fb24_37]],["name"]=[[八十四盘]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb24_35]]},["fb24_37"]={["down"]=[[fb24_38]],["dsc"]=[[八十四盘，道路艰险陡峭，迂回盘折，令人不能喘息。路左是蔽日遮天的冷杉林，路右是深不见底的绝壁峡谷。由此往上至接引殿，北下到洗象池。]],["fightBackground"]=[[山外]],["id"]=[[fb24_37]],["name"]=[[八十四盘]],["permission"]=2,["rightUp"]=[[fb24_36]],["stepMusic"]=[[jiaobu]]},["fb24_38"]={["dsc"]=[[八十四盘，道路艰险陡峭，迂回盘折，令人不能喘息。路左是蔽日遮天的冷杉林，路右是深不见底的绝壁峡谷。由此往上至接引殿，北下到洗象池。]],["fightBackground"]=[[山外]],["id"]=[[fb24_38]],["item1"]=[[fb24item100]],["name"]=[[八十四盘]],["permission"]=2,["rightDown"]=[[fb24_40]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_37]]},["fb24_39"]={["down"]=[[fb24_41]],["dsc"]=[[太子坪万行庵是古智禅师创建的。庵外满山长满莎椤花，花数芭合成一朵，叶子包在花外，古人以其根坚难易而盛赞之，以喻洁身自好之高贵品质。]],["id"]=[[fb24_39]],["name"]=[[万行庵]],["permission"]=2,["right"]=[[fb24_40]],["role1"]=[[fb24r39_1]],["stepMusic"]=[[jiaobu]]},["fb24_40"]={["dsc"]=[[接引殿右边濒崖，是金钢嘴。崖下有一块巨石，形状似钟，故名「钟石」。对面有一石，高耸十余丈，叫「仙人石」。]],["id"]=[[fb24_40]],["left"]=[[fb24_39]],["leftUp"]=[[fb24_38]],["name"]=[[接引殿]],["permission"]=2,["role1"]=[[fb24r40_1]],["role2"]=[[fb24r40_2]],["stepMusic"]=[[jiaobu]]},["fb24_41"]={["down"]=[[fb24_43]],["dsc"]=[[这就是峨眉山的主峰金顶了。登上金顶，视野豁然开朗，鸟看脚下，但见群峰涌绿叠翠，三江如丝如带；回首远眺，则见大雪山横亘天际，贡嘎山直插苍穹。]],["id"]=[[fb24_41]],["item1"]=[[ycitem3]],["leftDown"]=[[fb24_42]],["name"]=[[金顶]],["permission"]=2,["role1"]=[[fb24r41_1]],["role2"]=[[fb24r41_2]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_39]]},["fb24_42"]={["down"]=[[fb24_44]],["dsc"]=[[卧云庵旁边有个井络泉，据说以前曾因饮水人多而干涸，众尼为之诵经，于是泉水复出。出了卧云庵便是睹光台，旁边是华藏庵。]],["id"]=[[fb24_42]],["name"]=[[卧云庵]],["permission"]=2,["rightUp"]=[[fb24_41]],["role1"]=[[fb24r42_1b]],["role2"]=[[fb24r42_100]],["stepMusic"]=[[jiaobu]]},["fb24_43"]={["dsc"]=[[华藏庵是金顶的主要建筑，规模宏大，中祀普贤菩萨，旁列万佛。旁边是卧云庵。]],["id"]=[[fb24_43]],["name"]=[[华藏庵]],["permission"]=2,["role1"]=[[fb24r43_1]],["role2"]=[[fb24r43_2]],["role3"]=[[fb24r43_3]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_41]]},["fb24_44"]={["dsc"]=[[金顶云海，迷迷茫茫，笼罩四野，远接天际。云海轻荡时，你在金顶，脚踏白云，大有飘飘欲仙之感；当云涛迅猛涌来时，整个金顶都似在向前浮动，令人有乘舟欲风之意。]],["id"]=[[fb24_44]],["item1"]=[[fb24item101]],["name"]=[[睹光台]],["permission"]=2,["stepMusic"]=[[jiaobu]],["up"]=[[fb24_42]]},["fb24_45"]={["down"]=[[fb24_45]],["dsc"]=[[这就是峨眉第一大洞，洞内深窈无比，神秘难测。你一走进来，便发觉洞中叉洞多如迷宫，怪异莫测，似乎黝黑无底。还是快快离开吧。]],["id"]=[[fb24_45]],["left"]=[[fb24_46]],["name"]=[[九老洞]],["permission"]=2,["right"]=[[fb24_45]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_30]]},["fb24_46"]={["down"]=[[fb24_46]],["dsc"]=[[这就是峨眉第一大洞，洞内深窈无比，神秘难测。你一走进来，便发觉洞中叉洞多如迷宫，怪异莫测，似乎黝黑无底。还是快快离开吧。]],["id"]=[[fb24_46]],["left"]=[[fb24_47]],["name"]=[[九老洞]],["permission"]=2,["right"]=[[fb24_30]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_46]]},["fb24_47"]={["down"]=[[fb24_47]],["dsc"]=[[这就是峨眉第一大洞，洞内深窈无比，神秘难测。你一走进来，便发觉洞中叉洞多如迷宫，怪异莫测，似乎黝黑无底。还是快快离开吧。]],["id"]=[[fb24_47]],["left"]=[[fb24_48]],["name"]=[[九老洞]],["permission"]=2,["right"]=[[fb24_30]],["role1"]=[[fb24r47_1]],["stepMusic"]=[[jiaobu]],["up"]=[[fb24_47]]},["fb24_48"]={["down"]=[[fb24_24]],["dsc"]=[[这就是峨眉第一大洞，洞内深窈无比，神秘难测。你一走进来，便发觉洞中叉洞多如迷宫，怪异莫测，似乎黝黑无底。还是快快离开吧。]],["id"]=[[fb24_48]],["left"]=[[fb24_30]],["name"]=[[九老洞]],["permission"]=2,["right"]=[[fb24_48]],["stepMusic"]=[[jiaobu]],["